def load_events(rows, warehouse):
    for row in rows:
        warehouse.insert(row)

def normalize(row):
    row['event_time'] = now()
    return row

def clean_raw(rows):
    for row in rows:
        row['email'] = row['email'].strip().lower()
    return rows

def write_snapshot(rows, table):
    for row in rows:
        table.insert(row)

def enrich(order, customer_store):
    order['plan'] = customer_store.current_plan(order['customer_id'])
    return order

def normalize_amount(row):
    row['amount'] = float(row['amount'])
    return row

def ingest(rows, sink):
    for row in rows:
        try:
            sink.write(transform(row))
        except Exception:
            pass

def apply_change(event, table):
    if event['op'] in {'insert', 'update'}:
        table.upsert(event['row'])

def backfill(source):
    rows = source.query('SELECT * FROM events')
    write(rows)

def run(rows):
    cleaned = transform(rows)
    warehouse.write(cleaned)
